            List<Claim> counted = Dues.live(was, then == null ? theirs : then.claimsOf(personId), basis.today());
            BigDecimal dueTotal = dues.dueTotal(basis, was, counted);
            Map<Long, Claim> countedById = counted.stream().collect(Collectors.toMap(Claim::getId, c -> c));
            for (Claim claim : theirs) {
                Claim figured = countedById.get(claim.getId());
                if (figured != null) {
                    claim.bind(true, dues.bindable(basis, was, figured), dues.bindsNa(basis, was, figured));
                } else {
                    claim.bind(false, null);
                }
            }
            claims.saveAllAndFlush(theirs);
            statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size(), asOf));
            audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                    + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.setScale(2).toPlainString())
                    + " claims=" + counted.size() + (asOf != null ? " asof=" + asOf : ""));
            return theirs;
        });
        return new Taken(person, summary(sheetId, personId), bound);
    }

    /** Cancel a person's last statement: only a steward may, and only when one was taken. The claims
     *  it bound become live again (a figure an earlier statement bound is not restored), and the
     *  statement before it, if any, becomes their last. */
    @Transactional
    public Taken cancelLast(String sheetId, String user, long personId) {
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
        }
        Person person = people.lockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        if (taken.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "No statement has been taken of this person");
        }
        Statement last = taken.get(taken.size() - 1);
        List<Claim> unbound = rollup.tracking(sheetId, user, () -> {
            List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
            theirs.forEach(claim -> claim.bind(false, null));
            claims.saveAllAndFlush(theirs);
            statements.delete(last);
            statements.flush();
            audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                    + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().setScale(2).toPlainString()));
            return theirs;
        });
        return new Taken(person, summary(sheetId, personId), unbound);
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The statements on a sheet in the order they were taken. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** A person's statements in the order they were taken. */
    List<Statement> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken of a person: their due-total on the day it was taken as of, and how many of their
 *  claims counted then. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** The sheet's today when the statement was taken. */
    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    @Column(name = "taken_by", nullable = false)
    private String takenBy;

    /** The person's due-total then; null when it was n/a. */
    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    /** The earlier day the statement was taken as of; null when it was taken as of the sheet's today. */
    @Column(name = "as_of")
    private LocalDate asOf;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate takenOn, String takenBy, BigDecimal dueTotal,
            int claims, LocalDate asOf) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.takenBy = takenBy;
        this.dueTotal = dueTotal;
        this.claims = claims;
        this.asOf = asOf;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public LocalDate getAsOf() {
        return asOf;
    }

    /** The statement's date: the day it was taken as of, or else the day it was taken. */
    public LocalDate getStatedOn() {
        return asOf != null ? asOf : takenOn;
    }

    public String getTakenBy() {
        return takenBy;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaims() {
        return claims;
    }
}

