-- The sheet's history: after each change that can move its figures, a revision of every claim,
-- person, rate and dated setting the change left different from its last revision (and of the
-- policy date), stamped with the sheet's today then. The sheet as it stood at the end of a day is
-- the last revision of each stamped on or before that day.
CREATE TABLE claim_revision (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id       BIGINT         NOT NULL,
    recorded_on    DATE           NOT NULL,
    person_id      BIGINT         NOT NULL,
    amount         DECIMAL(14, 2) NOT NULL,
    claim_date     DATE           NOT NULL,
    status         VARCHAR(20)    NOT NULL,
    settled_due    DECIMAL(14, 2),
    stated         BOOLEAN        NOT NULL,
    stated_due     DECIMAL(14, 2),
    stated_na      BOOLEAN        NOT NULL,
    corrected_date DATE,
    due_by         DATE           NOT NULL,
    deferred_until DATE
);
CREATE INDEX claim_revision_sheet ON claim_revision (sheet_id, id);

-- A person's grades and holds are kept as text: each grade "from:grade" and each hold "from..to"
-- (a day left blank when there is none), separated by ";".
CREATE TABLE person_revision (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    person_id    BIGINT        NOT NULL,
    recorded_on  DATE          NOT NULL,
    name         VARCHAR(200)  NOT NULL,
    grades       VARCHAR(4000) NOT NULL,
    holds        VARCHAR(4000) NOT NULL,
    retired_from DATE,
    terms        INT
);
CREATE INDEX person_revision_sheet ON person_revision (sheet_id, id);

CREATE TABLE rate_revision (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
        this.history = history;
        this.merges = merges;
        this.transfers = transfers;
        this.service = service;
        this.statements = statements;
        this.sheets = sheets;
    }

    /** The people on the sheet; as of a day when one is given, as they stood at the end of it (see
     *  {@link History}), that day standing in for the sheet's today. */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        String sheet = sheetId.trim();
        if (asOf != null) {
            Map<Long, StatementSummary> then = statements.summaries(sheet, asOf);
            Predicate<Person> clashingThen = service.clashing(sheet);
            Map<Long, Integer> place = new HashMap<>();
            List<Person> listed = service.list(sheet);
            for (int i = 0; i < listed.size(); i++) {
                place.put(listed.get(i).getId(), i);
            }
            return history.asOf(sheet, asOf).people().values().stream()
                    .sorted(Comparator.comparing((Person p) -> place.getOrDefault(p.getId(), Integer.MAX_VALUE))
                            .thenComparing(Person::getId))
                    .map(p -> PersonView.of(p, then.getOrDefault(p.getId(), StatementSummary.NONE), asOf,
                            clashingThen.test(p)))
                    .toList();
        }
        Map<Long, StatementSummary> summaries = statements.summaries(sheet);

